-- the hints shown, the latest call wins
---@type { buttons: fx.InstructionalButton[] }?
local shown
---@type fx.Scaleform?
local movie
local loading = false

---@param sf fx.Scaleform
---@param buttons fx.InstructionalButton[]
local function fill(sf, buttons)
  sf:call("CLEAR_ALL")
  sf:call("SET_CLEAR_SPACE", 200)
  for i, b in ipairs(buttons) do
    local controls = (type(b.control) == "table" and b.control or { b.control }) --[[@as integer[] ]]
    ---@type (string|integer)[]
    local args = { i - 1 }
    -- in reverse: the movie lists the keys of a slot from right to left
    for j = #controls, 1, -1 do args[#args + 1] = GetControlInstructionalButton(2, controls[j], true) end
    args[#args + 1] = b.label
    sf:call("SET_DATA_SLOT", table_unpack(args, 1, #args))
  end
  sf:call("SET_BACKGROUND_COLOUR", 0, 0, 0, 80)
  sf:call("DRAW_INSTRUCTIONAL_BUTTONS")
end

local function draw()
  local current = shown
  ---@cast movie -nil
  local keyboard = IsUsingKeyboard(2)
  fill(movie, current --[[@as { buttons: fx.InstructionalButton[] }]].buttons)
  rt.addTask(function()
    if shown == nil then
      ---@cast movie -nil
      movie:release()
      movie = nil
      return true
    end
    local nowKeyboard = IsUsingKeyboard(2)
    if shown ~= current or nowKeyboard ~= keyboard then
      current, keyboard = shown, nowKeyboard
      fill(movie --[[@as fx.Scaleform]], shown.buttons)
    end
    ;(movie --[[@as fx.Scaleform]]):drawFullscreen(255, 255, 255, 255, 0)
    return false
  end)
end

---@param buttons fx.InstructionalButton[]
