    if type(b) ~= "table" or type(b.label) ~= "string" then error(("Control.instructional: button %d needs a label"):format(i), 2) end
    local controls = type(b.control) == "table" and b.control or { b.control }
    for _, c in ipairs(controls --[[@as integer[] ]]) do checkControl("instructional", c) end
    copy[i] = { control = b.control, label = b.label }
  end
  local mine = { buttons = copy }
  shown = mine
  if movie == nil and not loading then
    loading = true
    fx.Scaleform.loadAsync("instructional_buttons"):next(function(sf)
      loading = false
      movie = sf
      if shown == nil then
        sf:release()
        movie = nil
        return
      end
      draw()
    end, function(err)
      loading = false
      log:error("instructional: %s", tostring(err))
    end)
  end
  return function() if shown == mine then shown = nil end end
